function v212LayerReading(w,l){const ta=l==='ta',pmap=ta?V212_PLANET_TA:V212_PLANET_EN,md=langPlanet(w.md,l),ad=langPlanet(w.ad,l),pd=langPlanet(w.pd,l);if(ta)return `${md} மகாதசை நீண்டகால பின்னணியில் ${pmap[w.md]||''} சார்ந்த பாடங்களை வலுப்படுத்துகிறது. அதன் உள்ளே ${ad} புக்தி எந்த வாழ்க்கை விஷயத்திற்கு அதிக கவனம் செல்கிறது என்பதை குறுக்குகிறது; ${pd} அந்தரம் அந்த பெரிய பின்னணியை குறுகிய கால முடிவு, சம்பவம் அல்லது செயல் தேவையாக கொண்டு வரும். மூன்று அடுக்குகளும் ஒரே திசையில் சேர்ந்தால் பலன் தெளிவாக வெளிப்படும்; வேறு திசைகளில் இருந்தால் வாய்ப்புடன் பொறுப்பும் சேர்ந்து வரலாம்.`;return `${md} Mahadasha sets the long background through themes of ${pmap[w.md]||''}. Within it, ${ad} Bhukti narrows the active agenda, while ${pd} Antaram works as the nearer trigger for a decision, development or action. When the three levels converge the result is clearer; when they pull differently, opportunity and responsibility can arrive together.`}
function v212OverallVerdict(picks,l){const ta=l==='ta',vs=picks.map(x=>x.pick?.m?.verdict||'mixed'),support=vs.filter(x=>x==='support').length,pressure=vs.filter(x=>x==='pressure').length;if(support>pressure)return ta?'இந்த காலத்தின் மொத்த ஓட்டம் முன்னேற்றத்தை உருவாக்கக்கூடியது. ஆனால் பலன் வெளியிலிருந்து தானாக வருவதற்குப் பதில், ஏற்கனவே திறக்கும் வாய்ப்பை சரியான முடிவு மற்றும் தொடர்ந்து செய்யும் செயலால் பிடித்துக் கொள்வது முக்கியம்.':'The overall flow is constructive. Results are more likely to come from using an opening well than from passive good fortune.';if(pressure>support)return ta?'இந்த காலம் முதலில் பொறுப்பு, தாமதம் அல்லது திருத்தத்தை கேட்கலாம். பழைய குறையை சரிசெய்த பிறகு தான் அடுத்த முன்னேற்றம் நிலைபெறும்; அதனால் delay-ஐ failure என்று வாசிக்க வேண்டாம்.':'This period may first demand responsibility, delay or correction. Progress tends to consolidate after the underlying weakness is addressed, so delay should not be read as failure.';return ta?'இந்த காலம் கலப்பு தன்மை கொண்டது. ஒரு வாழ்க்கைப் பகுதியில் வாய்ப்பு திறக்கும் நேரத்தில் மற்றொரு பகுதியில் செலவு, குடும்பப் பொறுப்பு அல்லது தயக்கம் வரக்கூடும்; முன்னுரிமையை சரியாகத் தேர்வு செய்தால் காலத்தின் நல்ல பகுதியை பயன்படுத்த முடியும்.':'This is a mixed period. An opening in one area can coincide with expense, family duty or hesitation in another; choosing priorities well helps use the constructive side.'}
