function v136Timing(c,d,l,payload){window.__smvV136Payload=payload;const x=v136Chronology(c,d,payload),ta=l==='ta';const past=x.past.length?v136Window(x.past.slice().sort((a,b)=>b.score-a.score)[0],l):(ta?'தெளிவான கடந்தகால window இல்லை':'No distinct past window');const cur=x.current[0]?v136Window(x.current[0],l):(ta?'தற்போதைய தனி activation இல்லை':'No distinct current activation');const fut=x.future.length?v136Window(x.future.slice().sort((a,b)=>b.score-a.score)[0],l):(ta?'அடுத்த window கிடைக்கவில்லை':'No future window available');return ta?`கடந்தகால முக்கிய செயல்பாடு: ${past}. தற்போதைய நிலை: ${cur}. அடுத்த prospective செயல்பாடு: ${fut}. இவை நிகழ்வு நடந்ததற்கான ஆதாரம் அல்ல; வயது மற்றும் வாழ்க்கை வரலாற்றுடன் சேர்த்து மட்டுமே பொருள் கொள்ள வேண்டும்.`:`Strongest past activation: ${past}. Current: ${cur}. Next prospective activation: ${fut}. These are timing activations, not proof that an event occurred, and must be read with age and life history.`}
function v136MarriagePromise(c,data,l){const e=evidence(c,data,'marriage',l),a=smvAdvancedEvidence(c,data,'marriage',l),score=e.supporters.length+a.score.support-e.pressures.length-a.score.pressure+(e.occupants.length?1:0);if(l==='ta')return score>=1?'திருமண வாக்குறுதி: ஆதரவு காரணிகள் காணப்படுகின்றன; ஒரு தனி placement அடிப்படையில் திருமண மறுப்பு கூறப்படவில்லை.':score<=-2?'திருமண வாக்குறுதி: தாமதம்/உறவு அழுத்தம் தரும் காரணிகள் வலுவாக உள்ளன; இருந்தாலும் இதை முழுமையான திருமண மறுப்பாக எடுத்துக்கொள்ள முடியாது.':'திருமண வாக்குறுதி: ஆதரவும் சவாலும் கலந்த அமைப்பு; D9 மற்றும் கால ஒத்திசைவு முக்கியம்.';return score>=1?'Marriage promise: supportive factors are present; no denial is inferred from a single placement.':score<=-2?'Marriage promise: delay/relationship-pressure factors are strong, but this is not treated as absolute denial.':'Marriage promise: mixed support and pressure; D9 and timing convergence are important.'}
function v136HumanTimingReading(c,d,l,payload){
 window.__smvV136Payload=payload;
 const ta=l==='ta',x=v136Chronology(c,d,payload),current=x.current?.[0]||null;
 const future=x.future?.length?x.future.slice().sort((a,b)=>b.score-a.score||+a.a-+b.a)[0]:null;
 const past=x.past?.length?x.past.slice().sort((a,b)=>b.score-a.score)[0]:null;
 const out=[];
 if(current)out.push(ta?`இப்போது ${v136Window(current,l)} காலம் இந்த வாழ்க்கைப் பகுதியை செயல்படுத்துகிறது. தற்போதைய சூழலில் வரும் வாய்ப்பு அல்லது அழுத்தத்தை அந்தத் துறையின் நடைமுறை நிலவரத்துடன் சேர்த்து வாசிக்க வேண்டும்.`:`The current period ${v136Window(current,l)} is activating this life area. Read the opportunity or pressure together with the person’s real circumstances rather than as a stand-alone event promise.`);
 else out.push(ta?'தற்போது இந்தத் துறைக்கு தனியாக மிக வலுவான தசை activation தெரியவில்லை; அதனால் உடனடி நிகழ்வை வற்புறுத்தாமல் அடுத்த வலுவான காலத்தைப் பார்க்க வேண்டும்.':'There is no unusually strong stand-alone current activation for this area, so the reading should not force an immediate event.');
 if(future)out.push(ta?`அடுத்து கவனிக்க வேண்டிய வலுவான சாத்திய காலம் ${v136Window(future,l)}. அந்த நேரத்தில் தொடர்புடைய வாய்ப்பு நடைமுறையில் தோன்றினால் அது ஜாதக காலத்துடன் ஒத்திசைகிறது என்று பார்க்கலாம்.`:`The next stronger prospective window is ${v136Window(future,l)}. If a relevant real-world opportunity appears then, it can be treated as timing convergence.`);
 if(past)out.push(ta?`முன்பு ${v136Window(past,l)} காலத்திலும் இதே வாழ்க்கைப் பகுதி வலுப்பட்டிருக்கலாம்; வாழ்க்கை வரலாறு கொடுக்கப்படாததால் நடந்த நிகழ்வை engine ஊகிக்காது.`:`A similar activation may have occurred around ${v136Window(past,l)}; because life history is not supplied, the engine does not invent what actually happened.`);
 if(d==='marriage')out.push(ta?'திருமண நிலை வழங்கப்படாததால் எதிர்கால உறவு activation-ஐ “மற்றொரு திருமணம்” என்று தானாக பெயரிடாது; அது உறவு, துணைவர் அல்லது குடும்ப முன்னேற்றக் காலமாகவும் இருக்கலாம்.':'Because marital status is not assumed, a future relationship activation is not automatically labelled another marriage; it may instead describe spouse, relationship or family development.');
 return out.join(' ');
}

