function v216SignName(i,l){return (l==='ta'?V216_SIGNS_TA:V216_SIGNS_EN)[Number(i)||0]||''}
function v216Sep(a,b){const d=Math.abs(norm(a)-norm(b));return Math.min(d,360-d)}
function v216Page(title,paras,l,kind='life'){
 const body=(paras||[]).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');
 // V20: semantic chapter, not a forced physical page. Browser print may flow several
 // related paragraphs naturally on one page and move only when space is insufficient.
 return `<article class="smv-v16-page smv-v20-rich-block smv-v16-${kind}" data-smv-v16-page="1"><h4>${esc(title)}</h4>${body}</article>`;
}
function v216StrengthText(p,l){if(!p)return l==='ta'?'கிரகத் தரவு கிடைக்கவில்லை.':'Planet data is unavailable.';const ta=l==='ta',st=p.strength||{},r=Number(p?.strength3?.ratio||0),bits=[];if(st.exalted)bits.push(ta?'உச்சம்':'exalted');if(st.ownSign)bits.push(ta?'சுய ராசி':'own sign');if(st.moolatrikona)bits.push(ta?'மூலத்திரிகோணம்':'moolatrikona');if(st.debilitated)bits.push(ta?'நீசம்':'debilitated');if(p.retrograde||p.isRetrograde)bits.push(ta?'வக்ரம்':'retrograde');if(Number.isFinite(r)&&r>0)bits.push(ta?`சட்பல விகிதம் ${r.toFixed(2)}×`:`Shadbala ratio ${r.toFixed(2)}×`);return bits.length?bits.join(' · '):(ta?'சாதாரண/கலப்பு பலநிலை; பிற காரணிகளுடன் சேர்த்து வாசிக்க வேண்டும்.':'ordinary/mixed strength; it should be judged with the rest of the chart.')}
function v216OwnedHouses(c,pn){const lag=ls(c),out=[];lords.forEach((x,i)=>{if(x===pn)out.push(house(i,lag))});return out}
function v216HouseAspectPlanets(c,h){const support=[],pressure=[];for(const pn of V216_PLANETS){const p=pm(c)[pn];if(!p)continue;if(hof(c,p)===h)continue;if(!aspects(c,pn,h))continue;if(['Jupiter','Venus','Mercury','Moon'].includes(pn))support.push(pn);else pressure.push(pn)}return {support,pressure}}
