function v244VargaSentence(c,data,d,l){const q=domains[d],ta=l==='ta';if(!q?.v||!division(data,q.v))return'';const lord=lords[(ls(c)+q.h-1)%12],dg=v215VargaDignity(data,q.v,lord);if(dg>0)return ta?`D${q.v} இல் இந்தத் துறையின் அதிபதி ஆதரவு பெறுவதால் D1-ல் தெரியும் வாக்குறுதி நீண்டகாலத்தில் பயன்படுத்தக்கூடியதாக உறுதி பெறுகிறது.`:`D${q.v} supports the domain lord, giving the D1 promise stronger long-term confirmation.`;if(dg<0)return ta?`D${q.v} முழு ஆதரவை தராததால் D1 வாய்ப்பு இருந்தாலும் பலனை நிலைப்படுத்த நேரம், தேர்வு மற்றும் நடைமுறைத் தயாரிப்பு முக்கியமாகும்.`:`D${q.v} is less supportive, so timing, selection and practical preparation matter even when D1 shows promise.`;return ta?`D${q.v} கலப்பு உறுதிப்பாட்டை தருகிறது; ஒரு நல்ல காலம் வந்தாலும் முடிவின் தரத்தை மனிதத் தேர்வு மற்றும் தொடர்ச்சியான செயல் தீர்மானிக்கும்.`:`D${q.v} is mixed; a supportive period still needs good choices and sustained action.`}
