function v244CrossDomainHtml(c,data,l,payload){const ta=l==='ta';return `<section class="smv-v244-cross"><h3>${ta?'வாழ்க்கைப் பகுதிகள் ஒன்றை ஒன்று எப்படி மாற்றுகின்றன':'How life areas modify one another'}</h3>${V244_CROSS.map((g,i)=>{const states=g.ds.map(d=>({d,state:v244State(c,data,d),score:v243NatalScore(c,data,d)})),good=states.filter(x=>x.state==='support').length,bad=states.filter(x=>x.state==='pressure').length,names=g.ds.map(d=>v53DomainName(d,l)),lead=good>bad?(ta?`${names[0]} பகுதியில் கிடைக்கும் வலிமையை ${names[1]} மற்றும் ${names[2]} பகுதிகளுக்கு மாற்றி பயன்படுத்த முடியும்.`:`Strength in ${names[0]} can be converted into progress in ${names[1]} and ${names[2]}.`):bad>good?(ta?`${names[0]} பகுதியில் வரும் அழுத்தத்தை தனியாக கையாளாமல் ${names[1]} மற்றும் ${names[2]} உடன் இணைத்து சரிசெய்தால் நல்லது.`:`Pressure in ${names[0]} is better corrected together with ${names[1]} and ${names[2]} rather than in isolation.`):(ta?`${names.join('、')} ஒரே வேகத்தில் நகராது; ஒரு பகுதியில் முன்னேற்றம் மற்றொரு பகுதியில் நேரம்/பொறுப்பு கேட்கலாம்.`:`${names.join(', ')} will not move at the same speed; progress in one can demand time or responsibility in another.`),detail=ta?`இது ஒரே காரகத்தை மீண்டும் மூன்று முறை சொல்லும் பகுதி அல்ல. மூன்று துறைகளின் தனித்தனி ஜாதக score-ஐ இணைத்து எந்த துறை காரணம், எந்த துறை விளைவு, எது கட்டுப்பாட்டு புள்ளி என்பதைத் தேர்வு செய்கிறது.`:`This is not a repetition of one significator. The three domain scores are combined to identify cause, consequence and the control point.`;return `<article class="smv-v244-cross-item"><h4>${i+1}. ${esc(ta?g.ta:g.en)}</h4><p>${esc(lead)}</p><p>${esc(detail)}</p></article>`}).join('')}</section>`}
function v244PressurePlan(c,data,l,payload){const ta=l==='ta',rows=V53_ORDER.filter(d=>d!=='remedy').map(d=>({d,state:v244State(c,data,d),score:v243NatalScore(c,data,d)})).sort((a,b)=>a.score-b.score),focus=rows.filter(x=>x.state==='pressure').slice(0,5),out=[];if(!focus.length)out.push(ta?'வலுவான ஒரே pressure domain தெரியவில்லை. அதனால் பெரிய பரிகார பட்டியல் தேவையில்லை; routine, money, relationship boundaries மற்றும் health discipline போன்ற அடிப்படை ஒழுங்கைத் தொடர்வதே போதும்.':'No single pressure domain dominates, so a large remedy list is unnecessary; steady routine, money discipline, relationship boundaries and health habits are enough.');for(const x of focus){const action=v244Action(x.d,l);out.push(ta?`${v53DomainName(x.d,l)}: இந்தப் பகுதி முதலில் நடைமுறைத் திருத்தம் கேட்கிறது. ${action}`:`${v53DomainName(x.d,l)}: this area needs practical correction first. ${action}`)}out.push(ta?'கோயில்/மந்திர/தான வழிபாடு குடும்ப மரபுக்கு ஏற்ப துணையாக இருக்கலாம்; ஆனால் வேலை, நிதி, உடல், சட்டம் அல்லது உறவு பிரச்சினைக்கு தேவையான நிபுணர் உதவியை மாற்றாது.':'Devotional practice can be supplementary, but it does not replace appropriate professional help for work, finance, health, legal or relationship problems.');return out}
function v244LifeHtml(c,data,l,payload){const ta=l==='ta',groups=V243_LIFE_GROUPS,ctx=v241ContextSummary(payload,l),mechanisms=v244DominantMechanisms(c,data,l);let html=`<p class="small">${esc(ctx)}</p><section class="smv-v244-overview"><h4>${ta?'இந்த ஜாதகத்தின் மைய வாழ்க்கைக் கதை':'The central life story of this chart'}</h4>${mechanisms.map(x=>`<p>${esc(x)}</p>`).join('')}<p>${esc(ta?'கீழே வரும் ஒவ்வொரு வாழ்க்கைப் பகுதியும் தனி template அல்ல. அதற்கான பாவம்/அதிபதி, தேவையான D7/D9/D10, வயது மற்றும் தற்போதைய வாழ்க்கை நிலை, MD/AD/PD மற்றும் அடுத்த timing ஆகியவை ஒன்றாக முடிவு செய்யப்பட்ட பிறகே மனித மொழியாக எழுதப்படுகிறது.':'Each life area below is produced only after combining its house/lord, relevant D7/D9/D10 confirmation, age and present-life context, MD/AD/PD and timing.')}</p></section>`;for(const g of groups){html+=`<section class="smv-v244-group"><h3>${esc(ta?g.ta:g.en)}</h3>`;for(const d of g.ds){if(d==='remedy')html+=v216Page(ta?'தனிப்பட்ட நடைமுறை பரிகாரத் திட்டம்':'Personalised practical remedial plan',v244PressurePlan(c,data,l,payload),l,'remedy');else html+=v244DomainHtml(c,data,d,l,payload)}html+='</section>'}html+=v244CrossDomainHtml(c,data,l,payload);html+=`<details class="smv-pred-evidence smv-v244-technical" data-print-technical="1"><summary>${ta?'தொழில்நுட்ப ஆதாரம் — 12 பாவம் / கிரகம் / வர்க்கம்':'Technical evidence — 12 houses / planets / vargas'}</summary>${v215AllHouseReading(c,data,l)}${v216DeepLifeReport(c,data,l,payload)}</details>`;return html}
function v244PeriodEvent(c,data,x,l,payload){if(!x)return'';const event=x.pick?v241AdaptPick(x.pick,x.d,l,payload||{}):'',st=x.pick?v240PickState(x.pick):'mixed',ta=l==='ta',name=v53DomainName(x.d,l);if(!event)return'';if(st==='support')return ta?`${name}: “${event}” இந்தக் காலத்தில் செயலில் மாறக்கூடிய முக்கிய வடிவம். அதை நடைமுறை வாய்ப்பு, பொறுப்பு அல்லது தெளிவான முடிவு உறுதிப்படுத்தினால் முன்னேற்றம் நிலையாகும்.`:`${name}: “${event}” is a principal manifestation that can become practical in this period when confirmed by a real opening or responsibility.`;if(st==='pressure')return ta?`${name}: “${event}” பற்றிய சூழல் உருவானாலும் உடனே முடிவு செய்யாமல் அதன் தடையை முதலில் சரிசெய்ய வேண்டும்; தாமதம் இங்கு மறுப்பு அல்ல.`:`${name}: a situation around “${event}” can arise, but the obstacle should be corrected before final commitment; delay is not denial.`;return ta?`${name}: “${event}” வாய்ப்பு மற்றும் மறுபரிசீலனை இரண்டையும் கொண்டிருக்கும்; நிபந்தனைகள் தெளிவான பிறகே அது உண்மையான முன்னேற்றமா என்பதை முடிவு செய்யலாம்.`:`${name}: “${event}” carries both opportunity and review; conditions should be clear before treating it as progress.`}
function v244DashaGroupedHtml(c,data,rows,l,payload){const ta=l==='ta',groups=v212BhuktiGroups(rows);return groups.map((g,gi)=>{const stats=v212GroupStats(g).slice(0,5);if(!stats.length)return'';const topRows=g.rows.slice().sort((a,b)=>Math.max(0,...(b.picks||[]).map(x=>Number(x.total||0)))-Math.max(0,...(a.picks||[]).map(x=>Number(x.total||0))));const topDomains=stats.map(s=>s.d),mdH=hof(c,g.md),adH=hof(c,g.ad),lead=ta?`${langPlanet(g.md,l)} மகாதசை ${placementMeaningTa(mdH)} சார்ந்த பெரிய பின்னணியை நடத்தும் போது, ${langPlanet(g.ad,l)} புக்தி ${placementMeaningTa(adH)} சார்ந்த முடிவுகளை முன் வரிசைக்கு கொண்டு வருகிறது. இந்த இரண்டு திசைகளில் ${topDomains.slice(0,3).map(d=>v53DomainName(d,l)).join('、')} அதிகமாக இணைகின்றன.`:`${g.md} Mahadasha sets a background through ${placementMeaningEn(mdH)}, while ${g.ad} Bhukti brings ${placementMeaningEn(adH)} closer to decision. The strongest combined areas are ${topDomains.slice(0,3).map(d=>v53DomainName(d,l)).join(', ')}.`;let s=0,p=0;for(const st of stats){s+=st.support||0;p+=st.pressure||0}const balance=s>p?(ta?'இந்த புக்தியில் வாய்ப்பு அளவு பொறுப்பை விட சற்றே அதிகம்; ஆனால் ஒரு நல்ல முடிவு வந்தால் அதை நிலைப்படுத்தும் வேலை உடனே தொடர வேண்டும்.':'Opportunity slightly outweighs pressure in this Bhukti, but any gain still needs consolidation.'):p>s?(ta?'இந்த புக்தியில் correction work முதலில் வருகிறது. பழைய சுமை/தாமதத்தை சரிசெய்த பிறகே புதிய வளர்ச்சி நம்பகமாகும்.':'Correction comes first in this Bhukti; new growth is more reliable after old pressure is handled.'):ta?'இந்த புக்தி இரு வேகத்தில் இயங்கும்: சில விஷயங்கள் முன்னேறும் போது மற்றவை நேரம், பணம் அல்லது பொறுப்பு கேட்கும். முன்னுரிமை தவறினால் நல்ல வாய்ப்பும் சுமையாக மாறலாம்.':'This Bhukti runs at two speeds: some areas advance while others demand time, money or responsibility.';const domainParas=topDomains.slice(0,4).map(d=>{const rec=v243RecFromRows(g.rows,d);if(!rec)return'';const x=rec.best;return `<p>${esc(v244PeriodEvent(c,data,{...x,d},l,payload))}</p>`}).join('');const keys=topRows.slice(0,5).map(z=>{const picks=(z.picks||[]).slice(0,2),events=picks.map(x=>v241AdaptPick(x.pick,x.d,l,payload||{})).filter(Boolean),age=v49Age(payload,v49Mid(z.w));if(!events.length)return'';const tone=picks.some(x=>v240PickState(x.pick)==='pressure')?(ta?'இந்தச் சாளரத்தில் முடிவு செய்வதை விட நிபந்தனைகளை சரி பார்க்க வேண்டும்.':'Use this window to verify conditions before committing.'):ta?'இந்தச் சாளரத்தில் தொடர்புடைய வாய்ப்பு வந்தால் செயலில் மாற்றுவதற்கான அடித்தளம் உள்ளது.':'A relevant real-world opening in this window has a usable base for action.';return `${z.w.start} → ${z.w.end}${age!=null?` (${ta?'வயது':'age'} ${age})`:''}: ${events.join(ta?'；':'; ')}. ${tone}`}).filter(Boolean);return `<section class="smv-pred-period smv-v244-dasha"><h3>${esc(g.start)} → ${esc(g.end)} · ${esc(langPlanet(g.md,l))}–${esc(langPlanet(g.ad,l))}</h3><p>${esc(lead)}</p><p>${esc(balance)}</p>${domainParas}${keys.length?`<h4>${ta?'இந்த புக்திக்குள் பலன் உண்மையில் மாறும் குறுகிய சாளரங்கள்':'Shorter windows where the expression changes'}</h4>${keys.map(x=>`<p>${esc(x)}</p>`).join('')}`:''}</section>`}).join('')}
function v244SlowTransitLinks(c,g,ranked,l){const ta=l==='ta',seen=new Set(),out=[];for(const pn of ['Jupiter','Saturn','Rahu','Ketu']){const samples=v215YearPlanetSamples(c,g,pn);for(const s of samples){const hit=ranked.find(d=>{const q=domains[d];return q.h===s.hl||q.rel.includes(s.hl)});if(!hit)continue;const k=`${pn}:${s.hl}:${hit}`;if(seen.has(k))continue;seen.add(k);out.push(ta?`${langPlanet(pn,l)} இந்த ஆண்டில் லக்னத்திலிருந்து ${s.hl}-ஆம் பாவத்தை இயக்குவதால் ${v53DomainName(hit,l)} பகுதியில் ${placementMeaningTa(s.hl)} சார்ந்த மாற்றம்/பொறுப்பு முக்கியமாகிறது. இது ${langPlanet(pn,l)}-ன் பொதுக் காரகத்தை மீண்டும் சொல்லுவது அல்ல; அந்த பாவத் தொடர்பு இந்த ஆண்டு எந்த வாழ்க்கைப் பகுதியில் வெளிப்படுகிறது என்பதைக் குறிக்கிறது.`:`${pn} activates house ${s.hl} from Lagna, linking ${v53DomainName(hit,l)} with ${placementMeaningEn(s.hl)} this year. This is a house-specific link, not a repetition of the planet's generic significations.`);break}if(out.length>=3)break}return out}
function v244TransitGroupedHtml(c,data,rows,l,payload){const ta=l==='ta';return v213YearGroups(rows).map(g=>{const map=v240Aggregate(c,data,g.rows,payload),ranked=V53_ORDER.filter(d=>map.get(d)&&d!=='remedy').sort((a,b)=>v242Rank(map.get(b))-v242Rank(map.get(a))).slice(0,5);if(!ranked.length)return'';const primary=ranked[0],secondary=ranked[1],ps=v242State(map.get(primary)),ss=secondary?v242State(map.get(secondary)):'quiet',age=v49Age(payload,new Date(Date.UTC(g.year,6,1))),intro=ta?`${g.year}${age!=null?` (வயது சுமார் ${age})`:''} ஆண்டின் மையம் ${v53DomainName(primary,l)}. ${secondary?`${v53DomainName(secondary,l)} இரண்டாம் இயக்கமாக இணைகிறது.`:''} ${ps==='support'?'முதன்மை துறை முன்னேற்றத்தைத் தேடுகிறது.':ps==='pressure'?'முதன்மை துறை முதலில் திருத்தத்தை கேட்கிறது.':'முதன்மை துறை வாய்ப்பும் மறுபரிசீலனையும் ஒன்றாகக் கொண்டுள்ளது.'}`:`The centre of ${g.year}${age!=null?` (approx. age ${age})`:''} is ${v53DomainName(primary,l)}${secondary?`, with ${v53DomainName(secondary,l)} as a secondary movement`:''}.`;const body=ranked.slice(0,4).map(d=>{const rec=map.get(d),best=rec?.best;return best?`<p>${esc(v244PeriodEvent(c,data,{...best,d},l,payload))}</p>`:''}).join('');const links=v244SlowTransitLinks(c,g,ranked,l),topRows=g.rows.slice().sort((a,b)=>Math.max(0,...(b.picks||[]).map(x=>Number(x.total||0)))-Math.max(0,...(a.picks||[]).map(x=>Number(x.total||0)))).slice(0,3),wins=topRows.map(z=>{const ev=(z.picks||[]).slice(0,2).map(x=>v241AdaptPick(x.pick,x.d,l,payload||{})).filter(Boolean);return ev.length?`${z.w.start} → ${z.w.end}: ${ev.join(ta?'；':'; ')}.`:''}).filter(Boolean);return `<section class="smv-pred-period smv-v244-transit"><h3>${g.year} · ${ta?'கோச்சாரம் மற்றும் தசை ஒருங்கிணைந்த வருட வாசிப்பு':'Annual transit + dasha synthesis'}</h3><p>${esc(v215DominantDasha(g,l)||'')}</p><p>${esc(intro)}</p>${body}${links.map(x=>`<p>${esc(x)}</p>`).join('')}${wins.length?`<h4>${ta?'இந்த ஆண்டில் கவனிக்க வேண்டிய துல்லியமான காலங்கள்':'Specific windows to watch this year'}</h4>${wins.map(x=>`<p>${esc(x)}</p>`).join('')}`:''}</section>`}).join('')}
function v244WindowSig(c,data,rs,payload){const map=v240Aggregate(c,data,rs,payload),ranked=V53_ORDER.filter(d=>map.get(d)&&d!=='remedy').sort((a,b)=>v242Rank(map.get(b))-v242Rank(map.get(a))).slice(0,3);return {map,ranked,sig:ranked.map(d=>`${d}:${v242State(map.get(d))}`).join('|')}}
function v244WindowNarrative(c,data,map,ranked,l,payload){const ta=l==='ta';if(!ranked.length)return'';const bits=[];for(const d of ranked){const rec=map.get(d),event=rec?.best?.pick?v241AdaptPick(rec.best.pick,d,l,payload||{}):'',st=v242State(rec);if(!event)continue;bits.push(st==='support'?(ta?`${v53DomainName(d,l)} பகுதியில் “${event}” செயலில் மாறும் வாய்ப்பு அதிகம்`:`${v53DomainName(d,l)} is more likely to convert into “${event}”`):st==='pressure'?(ta?`${v53DomainName(d,l)} பகுதியில் “${event}” முன் தடையை சரிசெய்ய வேண்டும்`:`${v53DomainName(d,l)} needs correction before “${event}”`):(ta?`${v53DomainName(d,l)} பகுதியில் “${event}” பற்றி தேர்வு/மறுபரிசீலனை தேவை`:`${v53DomainName(d,l)} needs selection/review around “${event}”`))}return ta?`${bits.join('；')}. இந்தச் சாளரத்தின் முடிவு, எல்லா துறைகளையும் ஒரே நேரத்தில் நகர்த்துவதில் அல்ல; முதன்மை இயக்கத்தைச் சரியாக கையாள்ந்து அதற்குப் பிறகு இரண்டாம் துறையை இணைப்பதில் உள்ளது.`:`${bits.join('; ')}. The value of the window lies in handling the primary movement first rather than pushing every area at once.`}
function v244TimelineHtml(c,data,rows,l,payload){const ta=l==='ta',range=v240TimelineRange(payload),usable=rows.filter(z=>v240Overlap(z.w,range.start,range.end));if(range.end<range.start||!usable.length)return `<p>${ta?'80 வயது வரம்பிற்குள் வருட/மாத timeline இல்லை.':'No year/month timeline remains inside the age-80 limit.'}</p>`;const firstY=range.start.getUTCFullYear(),lastY=range.end.getUTCFullYear();let html=`<div class="adv-section smv-v244-timeline"><h3>🗓️ ${ta?'2026–2030 போன்ற காலவரிசை — பலன் மாறும் இடங்கள் மட்டும்':'Detailed timeline — only where the prediction state changes'}</h3><p class="small">${ta?'ஒவ்வொரு மாதத்திலும் ஒரே வார்த்தைகளை மீண்டும் எழுதாது. MD/AD/PD, event candidate மற்றும் domain state மாறும் போது மட்டும் புதிய காலச் சாளரம் உருவாகிறது.':'The same wording is not repeated every month. A new window appears only when MD/AD/PD, event candidate or domain state materially changes.'}</p>`;for(let y=firstY;y<=lastY;y++){const ya=new Date(Date.UTC(y,y===firstY?range.start.getUTCMonth():0,1)),yb=new Date(Date.UTC(y,y===lastY?range.end.getUTCMonth()+1:12,0,23,59,59)),yr=usable.filter(z=>v240Overlap(z.w,ya,yb));if(!yr.length)continue;const annual=v244WindowSig(c,data,yr,payload),age=v49Age(payload,new Date(Date.UTC(y,6,1)));html+=`<section class="smv-pred-period smv-v244-year"><h4>${y}${age!=null?` · ${ta?'வயது சுமார்':'approx. age'} ${age}`:''}</h4><p>${esc(v244WindowNarrative(c,data,annual.map,annual.ranked,l,payload))}</p>`;const fm=y===firstY?range.start.getUTCMonth():0,lm=y===lastY?range.end.getUTCMonth():11,snaps=[];for(let m=fm;m<=lm;m++){const a=new Date(Date.UTC(y,m,1)),b=new Date(Date.UTC(y,m+1,0,23,59,59)),rs=yr.filter(z=>v240Overlap(z.w,a,b));if(!rs.length)continue;const q=v244WindowSig(c,data,rs,payload);snaps.push({y,m,a,b,rs,...q})}const wins=[];for(const q of snaps){const prev=wins[wins.length-1];if(prev&&prev.sig===q.sig&&q.m===prev.end.m+1){prev.end=q;prev.rs.push(...q.rs)}else wins.push({sig:q.sig,start:q,end:q,rs:[...q.rs]})}for(const w of wins){const q=v244WindowSig(c,data,w.rs,payload),label=v243WindowLabel(w.start.a,w.end.b,l);html+=`<article class="smv-v244-month-window"><h5>${esc(label)}</h5><p>${esc(v244WindowNarrative(c,data,q.map,q.ranked,l,payload))}</p></article>`}html+='</section>'}return html+'</div>'}

