function v246SlowSegments(c,g,pn,payload){const rows=(g.rows||[]).slice().sort((a,b)=>+(dt(a.w?.start)||0)-+(dt(b.w?.start)||0)),out=[];for(const z of rows){const p=v39TransitPlanets(z.tr).find(x=>P(x.name||x.planet)===pn);if(!p)continue;const hl=v39TransitHouse(c,p),a=dt(z.w?.start),b=dt(z.w?.end,true);if(!a||!b)continue;const last=out[out.length-1],gap=last?(+a-+last.end):Infinity;if(last&&last.hl===hl&&gap<=3*86400000){if(+b>+last.end)last.end=b;continue}out.push({pn,hl,start:a,end:b,age:v49Age(payload,new Date((+a+ +b)/2))})}return out}
